DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `breakdown_count`(start_date varchar(45), finish_date varchar(45))
BEGIN
	SET SQL_MODE = 0;
	select count(BD.id) as total, case when BD.remark is null then "ไม่ระบุสาเหตุ" 
		else BC.case_name end as remark
	from breakdown_data BD
    left join breakdown_case BC on BC.case_code = BD.remark
    where date(BD.breakdown_start) >= start_date and date(BD.breakdown_finish) <= finish_date
	group by BD.remark
	order by count(BD.id) desc;
END ;;
DELIMITER ;
