DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `breakdown_insert`()
BEGIN
    set @chk_data_start = (
		select breakdown_start
        from breakdown_data
        order by id desc limit 1
    );
	
    set @chk_data_finish = (
		select breakdown_finish
        from breakdown_data
        order by id desc limit 1
    );
    
    if(@chk_data_finish is not null or @chk_data_start is null) then
		insert into breakdown_data(breakdown_start, time_stamp)
		values(now(), now());
	end if;
END ;;
