CREATE DEFINER=`root`@`localhost` PROCEDURE `breakdown_report`(start_date varchar(45), finish_date varchar(45))
BEGIN
	SELECT B.breakdown_start , B.breakdown_finish , C.case_name as remark,
    TIME_FORMAT(timediff(B.breakdown_finish, B.breakdown_start), '%H:%i:%s') as breakdown_time 
    FROM breakdown_data B
    left join breakdown_case C on C.case_code = B.remark
    where date(B.breakdown_start) >= start_date and date(B.breakdown_finish) <= finish_date
    order by B.breakdown_start asc;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
