CREATE DEFINER=`root`@`localhost` PROCEDURE `breakdown_status`()
BEGIN
	set @chk_data_start = (
		select breakdown_start
        from breakdown_data
        order by id desc limit 1
    );
	
    set @chk_data_finish = (
		select breakdown_finish
        from breakdown_data
        order by id desc limit 1
    );
    
    if(@chk_data_finish is null and @chk_data_start is not null) then
		select "true" as result;
	else
		select "false" as result;
	end if;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
