DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `breakdown_sum`(start_date varchar(45), finish_date varchar(45))
BEGIN
	set sql_mode = 0;
    
	SELECT case when C.case_name is null then 'ไม่ระบุสาเหตุ' else C.case_name end as remark,
    sum(TIME_TO_SEC(timediff(B.breakdown_finish, B.breakdown_start))) as breakdown_time_sec,
    sum(TIME_TO_SEC(timediff(B.breakdown_finish, B.breakdown_start))) / 60 as breakdown_time_min,
    sec_to_time(sum(TIME_TO_SEC(timediff(B.breakdown_finish, B.breakdown_start)))) as breakdown_time
    FROM breakdown_data B
    left join breakdown_case C on C.case_code = B.remark
    where date(B.breakdown_start) >= start_date and date(B.breakdown_finish) <= finish_date
    group by C.case_name
    order by sum(TIME_TO_SEC(timediff(B.breakdown_finish, B.breakdown_start))) desc;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
