CREATE DEFINER=`root`@`localhost` PROCEDURE `breakdown_update`()
BEGIN
	set @chk_data_start = (
		select breakdown_start
        from breakdown_data
        order by id desc limit 1
    );
	
	set @chk_data = (
		select breakdown_finish
        from breakdown_data
        order by id desc limit 1
    );
	
    if(@chk_data is null and @chk_data_start is not null) then
		set @id_update = (
			select id
			from breakdown_data
			order by id desc limit 1
		);
        update breakdown_data set breakdown_finish = now() where id = @id_update;
    end if;
END ;;
