CREATE DEFINER=`root`@`localhost` PROCEDURE `cal_diff`()
BEGIN
	set @plan = (select plan from job order by id desc limit 1);
    
    select @plan - actual as diff
    from actual_data
    order by id desc limit 1;
END ;;
