CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_actual`()
BEGIN
	set @actual = (
		select actual from actual_data order by id desc limit 1
    );
    
    set @ng = (
		select ng from actual_data order by id desc limit 1
    );
    
    if(@actual is null) then
		set @actual = 0;
	end if;
    
    if(@ng is null) then
		set @ng = 0;
	end if;
    
    set @actual = @actual + 1;
    
    insert into actual_data (actual, ng, time_stamp) values (@actual, @ng , now());
    
END ;;
