                                p_name varchar(45), emp_name varchar(45),
                                plan_qty int, job_st varchar(45), job_fs varchar(45))
BEGIN
	set @id_machine = (
		select id from machine where machine_name = mc_name
    );
    set @id_product = (
		select id from product where product_name = p_name
    );
    set @id_employee = (
