CREATE DEFINER=`root`@`localhost` PROCEDURE `update_breakdown`(time_update varchar(100), case_update varchar(500))
BEGIN
	SET SQL_SAFE_UPDATES = 0;
    
    set @case_code = (
		select case_code
        from breakdown_case
        where case_name = case_update
    );
	
	update breakdown_data set remark = @case_code where time_update = concat(breakdown_start, ' - ' , breakdown_finish);
    
END ;;
